//! Tests of the semantic search, model side: fp16 storage, image preprocessing (parity with PIL on the Phase 0 fixtures), query
//! normalisation. Synthetic images only (the PNG fixtures are generated by dev_tools/semantic/make_reference.py).
//!
//! Parity tests with the real model are `#[ignore]`: run them with
//!   SEMANTIC_MODEL_DIR=<folder with vision.onnx, text.onnx, tokenizer.json> cargo test semantic:: -- --ignored
//! The ONNX Runtime library is read from ORT_DYLIB_PATH, otherwise from the `models/` folder of an installed application.

use std::path::{Path, PathBuf};

use super::*;
use crate::semantic_models::active_model;

fn fixtures_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("src").join("tests").join("fixtures")
}

fn reference() -> serde_json::Value {
    serde_json::from_str(include_str!("fixtures/semantic_reference.json")).expect("semantic_reference.json")
}

fn cosine(a: &[f32], b: &[f32]) -> f64 {
    let dot: f64 = a.iter().zip(b).map(|(x, y)| *x as f64 * *y as f64).sum();
    let norm = |v: &[f32]| v.iter().map(|x| (*x as f64).powi(2)).sum::<f64>().sqrt();
    dot / (norm(a) * norm(b))
}

fn floats(value: &serde_json::Value) -> Vec<f32> {
    value.as_array().expect("array").iter().map(|item| item.as_f64().expect("number") as f32).collect()
}

// ---------------------------------------------------------------------------
// fp16
// ---------------------------------------------------------------------------

#[test]
fn known_half_values() {
    assert_eq!(f32_to_f16(0.0), 0x0000);
    assert_eq!(f32_to_f16(-0.0), 0x8000);
    assert_eq!(f32_to_f16(1.0), 0x3c00);
    assert_eq!(f32_to_f16(0.5), 0x3800);
    assert_eq!(f32_to_f16(-2.0), 0xc000);
    assert_eq!(f32_to_f16(65504.0), 0x7bff);
    assert_eq!(f32_to_f16(70000.0), 0x7c00, "overflow gives infinity");
    assert_eq!(f32_to_f16(f32::NEG_INFINITY), 0xfc00);
    assert!(f16_to_f32(f32_to_f16(f32::NAN)).is_nan());
    assert_eq!(f32_to_f16(5.960_464_5e-8), 0x0001, "smallest subnormal");
    assert_eq!(f32_to_f16(1e-8), 0x0000, "below half the smallest subnormal");
    assert_eq!(f32_to_f16(6.103_515_6e-5), 0x0400, "smallest normal");
    // Round half to even: 1 + 2^-11 is exactly between 1 and the next half (1 + 2^-10): stays 1.
    assert_eq!(f32_to_f16(1.0 + 1.0 / 2048.0), 0x3c00);
    assert_eq!(f32_to_f16(1.0 + 3.0 / 2048.0), 0x3c02);
}

#[test]
fn every_half_survives_a_round_trip() {
    for half in 0..=u16::MAX {
        let is_nan = (half & 0x7c00) == 0x7c00 && (half & 0x03ff) != 0;
        if is_nan { continue; }
        assert_eq!(f32_to_f16(f16_to_f32(half)), half, "half {half:#06x}");
    }
}

#[test]
fn embedding_values_keep_half_precision() {
    // Values of an L2-normalised 768-vector are small: relative error at most 2^-11 (normal range), absolute below 2^-25 otherwise.
    let mut state = 12345u64;
    for _ in 0..100_000 {
        state = state.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
        let value = ((state >> 40) as f32 / (1u64 << 24) as f32) * 2.0 - 1.0;
        let back = f16_to_f32(f32_to_f16(value));
        let error = (back - value).abs();
        assert!(error <= value.abs() / 2048.0 + 3e-8, "{value} -> {back}");
    }
}

#[test]
fn blob_has_two_bytes_per_dimension() {
    let dim = active_model().embed_dim;
    let mut vector: Vec<f32> = (0..dim).map(|index| ((index as f32) * 0.37).sin()).collect();
    l2_normalise(&mut vector);
    let blob = vector_to_blob(&vector);
    assert_eq!(blob.len(), dim * 2);
    let back = blob_to_vector(&blob, dim).expect("same length");
    assert!(cosine(&vector, &back) > 0.99999);
    assert!(blob_to_vector(&blob[..blob.len() - 2], dim).is_none());
    assert!(blob_to_vector(&blob, dim + 1).is_none());
}

// ---------------------------------------------------------------------------
// Image preprocessing
// ---------------------------------------------------------------------------

#[test]
fn resize_keeps_a_uniform_image_uniform_and_skips_unchanged_sizes() {
    let rgb: Vec<u8> = [17u8, 128, 250].repeat(37 * 23);
    let resized = resize_bilinear(&rgb, 37, 23, 224, 224);
    assert_eq!(resized.len(), 224 * 224 * 3);
    assert!(resized.chunks_exact(3).all(|pixel| pixel == [17, 128, 250]));
    let pattern: Vec<u8> = (0..20 * 10 * 3).map(|index| (index * 7 % 256) as u8).collect();
    assert_eq!(resize_bilinear(&pattern, 20, 10, 20, 10), pattern);
}

#[test]
fn image_tensor_has_the_model_shape_and_range() {
    let model = active_model();
    let rgb: Vec<u8> = (0..300 * 200 * 3).map(|index| (index * 13 % 256) as u8).collect();
    let tensor = image_tensor(&rgb, 300, 200, model);
    assert_eq!(tensor.len(), 3 * model.image_size * model.image_size);
    assert!(tensor.iter().all(|value| (-1.0..=1.0).contains(value)));
    // Black and white map to the ends of the range.
    let black = image_tensor(&[0u8; 3 * 4], 2, 2, model);
    let white = image_tensor(&[255u8; 3 * 4], 2, 2, model);
    assert!(black.iter().all(|&value| value == -1.0) && white.iter().all(|&value| value == 1.0));
}

#[test]
fn preprocessing_matches_pil_on_the_reference_images() {
    let model = active_model();
    let size = model.image_size;
    // Positions (channel, y, x) of the probes written by make_reference.py.
    let positions = [(0usize, 0usize, 0usize), (1, 111, 57), (2, 223, 223), (0, 100, 200)];
    for image in reference()["images"].as_array().unwrap() {
        let file = image["file"].as_str().unwrap();
        let (rgb, width, height) = crate::integrity::decode_png(&fixtures_dir().join(file), true).expect("fixture PNG");
        let tensor = image_tensor(&rgb, width, height, model);
        let expected = floats(&image["pixel_probe"]);
        for ((channel, y, x), want) in positions.iter().zip(expected) {
            let got = tensor[channel * size * size + y * size + x];
            assert!((got - want).abs() < 1e-3, "{file} ({channel}, {y}, {x}): {got} instead of {want}");
        }
    }
}

